package com.qiban.companion;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import org.json.*;

/** The iOS archive schema, including per-persona independent message/memory/diary sessions. */
final class ArchiveStore {
    final File directory;private final File file;private JSONObject archive;
    ArchiveStore(File directory)throws Exception {this.directory=directory;file=new File(directory,"archive.json");archive=file.exists()?FilesSupport.json(file,100*1024*1024):initial();prepare(archive);validate(archive);save(archive);}
    static double now(){return System.currentTimeMillis()/1000.0-978307200;}
    static double milliseconds(double swift){return (swift+978307200)*1000;}
    static String uuid(){return UUID.randomUUID().toString().toUpperCase(Locale.ROOT);}
    static String identifier(String value)throws Exception {try{return UUID.fromString(value).toString().toUpperCase(Locale.ROOT);}catch(IllegalArgumentException ignored){}byte[] h=MessageDigest.getInstance("SHA-256").digest(("qiban-chat:"+value).getBytes(StandardCharsets.UTF_8));java.nio.ByteBuffer b=java.nio.ByteBuffer.wrap(h);return new UUID(b.getLong(),b.getLong()).toString().toUpperCase(Locale.ROOT);}
    static JSONObject empty()throws Exception{return new JSONObject().put("messages",new JSONArray()).put("memories","").put("diary",new JSONArray());}
    static JSONObject defaultMood()throws Exception{return new JSONObject().put("emotion","calm").put("reason","初次见面，平静陪伴。").put("intensity",.25).put("closeness",.25).put("updatedAt",now());}
    static JSONObject card(String id,String name,String description)throws Exception {return new JSONObject().put("id",id).put("name",name).put("title",name).put("description",description).put("personality","").put("scenario","").put("firstMessages",new JSONArray()).put("examples","").put("systemRules","").put("replyRules","").put("userName","").put("userDescription","").put("notes","").put("tags",new JSONArray());}
    static JSONObject initial()throws Exception {
        String id=uuid();JSONObject a=empty(),settings=new JSONObject().put("endpoint","").put("model","").put("temperature",0.7).put("persona","认真倾听，自然使用简体中文，不编造共同经历。");
        JSONObject library=new JSONObject().put("systemPrompt","自然使用简体中文，认真倾听，不编造共同经历。").put("userName","").put("userDescription","").put("bodyStyle","动作自然克制，与情绪和语气一致。").put("cards",new JSONArray().put(card(id,"伙伴",settings.getString("persona")))).put("defaultCardID",id).put("modelBindings",new JSONObject());
        settings.put("personas",library).put("speech",new JSONObject().put("enabled",true).put("autoPlay",false).put("voiceID","system.zh").put("language","zh").put("speed",1).put("volume",1).put("computeMode","automatic"));
        return a.put("schemaVersion",3).put("settings",settings).put("personaSessionKey",id);
    }
    static void prepare(JSONObject a)throws Exception {
        if(!List.of(1,2,3).contains(a.optInt("schemaVersion",1)))throw new IOException("不支持的备份版本，原资料未改变。");
        JSONObject settings=a.getJSONObject("settings"),lib=settings.optJSONObject("personas");if(lib==null){JSONObject template=initial().getJSONObject("settings").getJSONObject("personas");template.getJSONArray("cards").getJSONObject(0).put("description",settings.optString("persona"));settings.put("personas",lib=template);a.put("personaSessionKey",lib.getString("defaultCardID"));}
        if(settings.optJSONObject("speech")==null)settings.put("speech",initial().getJSONObject("settings").getJSONObject("speech"));
        if(!a.has("personaSessionKey"))a.put("personaSessionKey",lib.getString("defaultCardID"));
        JSONArray sessions=FilesSupport.array(a,"conversationSessions");JSONObject active=FilesSupport.object(a,"activeSessionIDs");FilesSupport.object(a,"sessionHistories");FilesSupport.object(a,"personaConversations");FilesSupport.object(a,"chatContactOrigins");
        for(int i=0;i<lib.getJSONArray("cards").length();i++){String key=lib.getJSONArray("cards").getJSONObject(i).getString("id");if(active.has(key))continue;String id=identifier("session:"+key+":default");JSONObject contents=key.equals(a.optString("personaSessionKey"))?a:a.getJSONObject("personaConversations").optJSONObject(key);JSONArray messages=contents==null?new JSONArray():contents.optJSONArray("messages");sessions.put(new JSONObject().put("id",id).put("personaKey",key).put("title",messages==null||messages.length()==0?"新对话":"原有对话").put("createdAt",now()).put("updatedAt",now()));active.put(key,id);}
        a.put("schemaVersion",3);
        JSONObject moods=FilesSupport.object(a,"moods");String owner=a.getString("personaSessionKey");if(!moods.has(owner))moods.put(owner,defaultMood());
    }
    synchronized JSONObject snapshot()throws Exception{return FilesSupport.copy(archive);}
    synchronized JSONObject settings()throws Exception{return FilesSupport.copy(archive.getJSONObject("settings"));}
    synchronized void save(JSONObject next)throws Exception {prepare(next);String owner=next.getString("personaSessionKey"),id=next.getJSONObject("activeSessionIDs").getString(owner);JSONObject meta=find(next.getJSONArray("conversationSessions"),id);meta.put("mood",next.getJSONObject("moods").getJSONObject(owner));validate(next);FilesSupport.atomic(file,next.toString());archive=FilesSupport.copy(next);}
    static JSONObject contents(JSONObject a,String sessionID)throws Exception {JSONObject meta=find(a.getJSONArray("conversationSessions"),sessionID);if(meta==null)throw new IOException("找不到这段对话。");String owner=meta.getString("personaKey");if(sessionID.equals(a.getJSONObject("activeSessionIDs").optString(owner))){if(owner.equals(a.optString("personaSessionKey")))return new JSONObject().put("messages",a.getJSONArray("messages")).put("memories",a.optString("memories")).put("diary",a.getJSONArray("diary"));return a.getJSONObject("personaConversations").optJSONObject(owner)==null?empty():a.getJSONObject("personaConversations").getJSONObject(owner);}JSONObject value=a.getJSONObject("sessionHistories").optJSONObject(sessionID);return value==null?empty():value;}
    static void setContents(JSONObject a,String id,JSONObject value)throws Exception {JSONObject meta=find(a.getJSONArray("conversationSessions"),id);String owner=meta.getString("personaKey");if(id.equals(a.getJSONObject("activeSessionIDs").optString(owner))){if(owner.equals(a.optString("personaSessionKey"))){a.put("messages",value.getJSONArray("messages")).put("memories",value.optString("memories")).put("diary",value.getJSONArray("diary"));}else a.getJSONObject("personaConversations").put(owner,value);}else a.getJSONObject("sessionHistories").put(id,value);meta.put("updatedAt",now());}
    static void select(JSONObject a,String id)throws Exception {JSONObject meta=find(a.getJSONArray("conversationSessions"),id);if(meta==null)throw new IOException("对话已不存在。");String owner=meta.getString("personaKey"),previous=a.getJSONObject("activeSessionIDs").optString(owner);if(id.equals(previous))return;JSONObject restored=contents(a,id);if(!previous.isEmpty()){a.getJSONObject("sessionHistories").put(previous,contents(a,previous));JSONObject oldMeta=find(a.getJSONArray("conversationSessions"),previous);oldMeta.put("mood",FilesSupport.object(a,"moods").optJSONObject(owner));}FilesSupport.object(a,"moods").put(owner,meta.optJSONObject("mood")==null?defaultMood():meta.getJSONObject("mood"));a.getJSONObject("activeSessionIDs").put(owner,id);a.getJSONObject("sessionHistories").remove(id);setContents(a,id,restored);}
    synchronized String newSession()throws Exception {JSONObject a=snapshot();String id=uuid(),key=a.getString("personaSessionKey");a.getJSONArray("conversationSessions").put(new JSONObject().put("id",id).put("personaKey",key).put("title","新对话").put("createdAt",now()).put("updatedAt",now()));a.getJSONObject("sessionHistories").put(id,empty());select(a,id);save(a);return id;}
    synchronized void chooseSession(String id)throws Exception {JSONObject a=snapshot();JSONObject m=find(a.getJSONArray("conversationSessions"),id);if(m==null||!m.getString("personaKey").equals(a.getString("personaSessionKey")))throw new IOException("这段对话属于其他角色。");select(a,id);save(a);}
    static JSONObject find(JSONArray values,String id){if(values==null)return null;for(int i=0;i<values.length();i++){JSONObject v=values.optJSONObject(i);if(v!=null&&v.optString("id").equals(id))return v;}return null;}
    synchronized JSONObject profile()throws Exception {
        JSONObject a=snapshot(),s=a.getJSONObject("settings"),lib=s.getJSONObject("personas"),origins=a.getJSONObject("chatContactOrigins"),speech=s.optJSONObject("speech");if(speech==null)speech=initial().getJSONObject("settings").getJSONObject("speech");JSONArray contacts=new JSONArray(),cards=lib.getJSONArray("cards");
        for(int i=0;i<cards.length();i++){JSONObject card=cards.getJSONObject(i);String key=card.getString("id");JSONArray sessions=new JSONArray();for(int j=0;j<a.getJSONArray("conversationSessions").length();j++){JSONObject m=a.getJSONArray("conversationSessions").getJSONObject(j);if(!m.getString("personaKey").equals(key))continue;JSONObject data=contents(a,m.getString("id"));sessions.put(new JSONObject().put("id",m.getString("id")).put("title",m.getString("title")).put("createdAt",milliseconds(m.getDouble("createdAt"))).put("updatedAt",milliseconds(m.getDouble("updatedAt"))).put("active",m.getString("id").equals(a.getJSONObject("activeSessionIDs").optString(key))).put("externalID",m.opt("externalID")).put("memories",data.optString("memories")));}
            contacts.put(new JSONObject().put("id",origins.optString(key,"qiban_"+key)).put("qibanId",key).put("name",card.getString("name")).put("description",card.optString("title")).put("prompt",prompt(card,lib)).put("examples",card.optString("examples")).put("source","qiban").put("tags",new JSONArray().put("App人设")).put("memories",contents(a,a.getJSONObject("activeSessionIDs").getString(key)).optString("memories")).put("resetToken","0").put("sessions",sessions));
        }
        JSONObject services=s.optJSONObject("services");return new JSONObject().put("contacts",contacts).put("speechFormat","【朗读格式】只把角色实际说出口的台词写在中文引号“”或日文「」中；动作、外貌、心理独白写在（圆括号）内，纯动作不编造台词。").put("globalPrompt",lib.optString("systemPrompt")+"\n【用户人设】\n"+lib.optString("userName")+"\n"+lib.optString("userDescription")).put("bodyNotice","当前为文字通讯，3D场景暂停，不要把文字描写当成身体已执行。").put("userName",lib.optString("userName").isEmpty()?"你":lib.optString("userName")).put("language",speech.optString("language","zh")).put("autoPlay",speech.optBoolean("autoPlay")).put("speechEnabled",speech.optBoolean("enabled",true)).put("model",s.optString("model")).put("temperature",s.optDouble("temperature",0.7)).put("configured",!s.optString("endpoint").isEmpty()&&!s.optString("model").isEmpty()).put("searchEnabled",services!=null&&services.optJSONObject("search")!=null&&services.getJSONObject("search").optBoolean("enabled")).put("activeId",origins.optString(a.getString("personaSessionKey"),"qiban_"+a.getString("personaSessionKey"))).put("nativeArchive",a.toString());
    }
    static String prompt(JSONObject card,JSONObject lib){String user=card.optString("userName").isEmpty()?lib.optString("userName","你"):card.optString("userName"),description=card.optString("userDescription").isEmpty()?lib.optString("userDescription"):card.optString("userDescription");StringBuilder p=new StringBuilder("角色姓名："+card.optString("name")+"\n");for(String key:List.of("description","personality","scenario","systemRules","replyRules","examples")){if(!card.optString(key).isEmpty())p.append(card.optString(key)).append('\n');}p.append("\n【用户】\n").append(user).append('\n').append(description).append("\n【身体表现偏好】\n").append(lib.optString("bodyStyle"));return p.toString().replace("{{char}}",card.optString("name")).replace("{{user}}",user);}
    synchronized JSONObject messages(String owner,String id,int offset)throws Exception {JSONObject a=snapshot();if(id.isEmpty())id=a.getJSONObject("activeSessionIDs").optString(owner);JSONObject m=find(a.getJSONArray("conversationSessions"),id);if(m==null||!m.getString("personaKey").equals(owner))return new JSONObject().put("messages",new JSONArray()).put("more",false).put("next",0);JSONArray list=contents(a,id).getJSONArray("messages"),result=new JSONArray();int end=Math.min(list.length(),Math.max(0,offset)+200);for(int i=Math.max(0,offset);i<end;i++){JSONObject row=list.getJSONObject(i),meta=new JSONObject();if(row.has("spokenJapanese"))meta.put("qibanSpokenJapanese",row.get("spokenJapanese"));if(row.has("spokenChinese"))meta.put("qibanSpokenChinese",row.get("spokenChinese"));result.put(new JSONObject().put("id",row.getString("id")).put("role",row.getString("role")).put("text",row.getString("content")).put("createdAt",milliseconds(row.getDouble("createdAt"))).put("meta",meta));}return new JSONObject().put("messages",result).put("next",end).put("more",end<list.length());}
    synchronized JSONObject sync(JSONObject change,boolean active)throws Exception {
        JSONObject a=snapshot(),lib=a.getJSONObject("settings").getJSONObject("personas");String original=change.getString("id"),key=change.optString("qibanId");if(key.isEmpty())key=identifier("contact:"+original);else key=identifier(key);JSONArray cards=lib.getJSONArray("cards");JSONObject card=find(cards,key);if(card==null&&!change.isNull("qibanId")&&!change.optString("qibanId").isEmpty())return new JSONObject().put("linked",false);
        boolean newCard=card==null;if(newCard){if(cards.length()>=50)return new JSONObject().put("linked",false);cards.put(card=card(key,change.getString("name"),change.optString("prompt")));}
        card.put("name",change.getString("name")).put("title",change.getString("name"));if(change.optBoolean("promptEdited")){card.put("description",change.optString("prompt")).put("examples",change.optString("examples"));for(String field:List.of("personality","scenario","systemRules","replyRules"))card.put(field,"");}a.getJSONObject("chatContactOrigins").put(key,original);prepare(a);
        String id=identifier(change.optString("sessionID",a.getJSONObject("activeSessionIDs").getString(key)));JSONObject meta=find(a.getJSONArray("conversationSessions"),id);if(meta==null){meta=new JSONObject().put("id",id).put("personaKey",key).put("createdAt",now()).put("updatedAt",now());a.getJSONArray("conversationSessions").put(meta);a.getJSONObject("sessionHistories").put(id,empty());}if(!meta.getString("personaKey").equals(key))throw new IOException("对话与角色不匹配。");meta.put("title",change.optString("sessionTitle","新对话")).put("externalID",change.optString("conversationID"));
        if(newCard){String previous=a.getJSONObject("activeSessionIDs").optString(key);if(!previous.equals(id)&&contents(a,previous).getJSONArray("messages").length()==0){JSONArray list=a.getJSONArray("conversationSessions"),filtered=new JSONArray();for(int i=0;i<list.length();i++)if(!list.getJSONObject(i).getString("id").equals(previous))filtered.put(list.getJSONObject(i));a.put("conversationSessions",filtered);a.getJSONObject("sessionHistories").remove(previous);a.getJSONObject("activeSessionIDs").put(key,id);a.getJSONObject("sessionHistories").remove(id);}}
        JSONObject data=contents(a,id);JSONArray old=data.getJSONArray("messages"),removed=change.optJSONArray("removedIds"),incoming=change.getJSONArray("messages");if(incoming.length()>300||(removed!=null&&removed.length()>300))throw new IOException("单次同步超过上限。");Set<String> deleted=new HashSet<>();if(removed!=null)for(int i=0;i<removed.length();i++){deleted.add(identifier(removed.getString(i)));deleted.add(identifier("message:"+original+":"+removed.getString(i)));}
        LinkedHashMap<String,JSONObject> messages=new LinkedHashMap<>();for(int i=0;i<old.length();i++){JSONObject m=old.getJSONObject(i);if(!deleted.contains(m.getString("id")))messages.put(m.getString("id"),m);}JSONObject ids=new JSONObject();for(int i=0;i<incoming.length();i++){JSONObject m=incoming.getJSONObject(i);String nativeID;try{UUID.fromString(m.getString("id"));nativeID=identifier(m.getString("id"));}catch(IllegalArgumentException e){nativeID=identifier("message:"+original+":"+m.getString("id"));}JSONObject n=new JSONObject().put("id",nativeID).put("role",m.getString("role")).put("content",m.optString("text")).put("createdAt",m.getDouble("createdAt")/1000-978307200);if(!m.isNull("spokenChinese"))n.put("spokenChinese",m.get("spokenChinese"));if(!m.isNull("spokenJapanese"))n.put("spokenJapanese",m.get("spokenJapanese"));messages.put(nativeID,n);ids.put(m.getString("id"),nativeID);}
        ArrayList<JSONObject> sorted=new ArrayList<>(messages.values());sorted.sort(Comparator.comparingDouble(m->m.optDouble("createdAt")));data.put("messages",new JSONArray(sorted));setContents(a,id,data);if(active)select(a,id);save(a);return new JSONObject().put("linked",true).put("qibanId",key).put("sessionID",id).put("messageIDs",ids);
    }
    static void validate(JSONObject a)throws Exception {
        JSONObject settings=a.getJSONObject("settings"),library=settings.getJSONObject("personas"),speech=settings.getJSONObject("speech");double temperature=settings.optDouble("temperature",.7),speed=speech.optDouble("speed",1),volume=speech.optDouble("volume",1);if(!Double.isFinite(temperature)||temperature<0||temperature>2||!Double.isFinite(speed)||speed<.7||speed>1.3||!Double.isFinite(volume)||volume<0||volume>1||!List.of("zh","ja").contains(speech.optString("language","zh")))throw new IOException("接口或配音参数无效。");
        JSONArray people=library.getJSONArray("cards");Set<String> peopleIDs=new HashSet<>();for(int i=0;i<people.length();i++){JSONObject p=people.getJSONObject(i);UUID.fromString(p.getString("id"));if(!peopleIDs.add(p.getString("id"))||p.getString("name").isEmpty()||p.getString("name").length()>120||p.getString("title").isEmpty()||p.getString("title").length()>120||p.getJSONArray("firstMessages").length()>20||p.getJSONArray("tags").length()>20)throw new IOException("角色卡格式无效。");for(String k:List.of("description","personality","scenario","examples","systemRules","replyRules","userDescription","notes"))if(p.optString(k).length()>1000000)throw new IOException("角色单字段超过100万字。");}if(!peopleIDs.contains(library.getString("defaultCardID")))throw new IOException("默认角色无效。");
        if(!List.of(1,2,3).contains(a.optInt("schemaVersion")))throw new IOException("不支持的备份版本。");JSONArray sessions=a.getJSONArray("conversationSessions"),cards=a.getJSONObject("settings").getJSONObject("personas").getJSONArray("cards");if(sessions.length()>1000||cards.length()<1||cards.length()>50)throw new IOException("对话或角色数量超过上限。");Set<String> all=new HashSet<>();long count=0;for(int i=0;i<sessions.length();i++){JSONObject meta=sessions.getJSONObject(i);String id=meta.getString("id");UUID.fromString(id);if(!all.add(id)||meta.getString("title").isEmpty()||meta.getString("title").length()>120)throw new IOException("对话索引无效。");JSONArray list=contents(a,id).getJSONArray("messages");count+=list.length();Set<String> ids=new HashSet<>();for(int j=0;j<list.length();j++){JSONObject m=list.getJSONObject(j);if(!ids.add(m.getString("id"))||!List.of("user","assistant").contains(m.getString("role"))||m.getString("content").length()>100000)throw new IOException("消息资料无效。");}}if(count>100000||a.toString().length()>100*1024*1024)throw new IOException("备份文字超过上限。");
    }
}
